import json
from datetime import datetime

def validate_and_ingest_cdp_events(
    raw_event_stream: list[dict]
) -> dict:
    """
    Validates, sanitizes, and parses inbound CDP event streams against canonical
    Segment/RudderStack semantic event specifications (Track, Identify, Page).
    """
    valid_events = []
    quarantined_events = []

    required_base_fields = {"event_id", "timestamp", "type", "anonymous_id"}
    valid_types = {"track", "identify", "page", "screen"}

    for raw_ev in raw_event_stream:
        missing_fields = required_base_fields - set(raw_ev.keys())
        if missing_fields:
            quarantined_events.append({"event": raw_ev, "reason": f"Missing required fields: {missing_fields}"})
            continue

        ev_type = raw_ev["type"]
        if ev_type not in valid_types:
            quarantined_events.append({"event": raw_ev, "reason": f"Invalid event type: {ev_type}"})
            continue

        if ev_type == "track":
            if "event_name" not in raw_ev or "properties" not in raw_ev:
                quarantined_events.append({"event": raw_ev, "reason": "Track event missing event_name or properties"})
                continue
        elif ev_type == "identify":
            if "user_id" not in raw_ev and "traits" not in raw_ev:
                quarantined_events.append({"event": raw_ev, "reason": "Identify event must contain user_id or traits"})
                continue

        enriched = raw_ev.copy()
        enriched["ingested_at"] = datetime.utcnow().isoformat() + "Z"
        valid_events.append(enriched)

    return {
        "total_events_received": len(raw_event_stream),
        "valid_events_ingested": len(valid_events),
        "quarantined_events_count": len(quarantined_events),
        "ingestion_success_rate": round((len(valid_events) / len(raw_event_stream)) * 100.0, 2),
        "sample_valid_event": valid_events[0] if valid_events else None,
        "quarantine_reasons": [q["reason"] for q in quarantined_events]
    }

if __name__ == '__main__':
