import numpy as np

def calculate_fellegi_sunter_weights(
    attribute_parameters: dict[str, dict[str, float]]
) -> dict:
    """
    Computes Fellegi-Sunter log-odds agreement and disagreement weights
    w_k = log2(m_k / u_k) and w'_k = log2((1 - m_k) / (1 - u_k)).
    """
    weights = {}
    for attr, params in attribute_parameters.items():
        m = params["m_prob"]
        u = params["u_prob"]

        w_agree = np.log2(m / u)
        w_disagree = np.log2((1.0 - m) / (1.0 - u))

        weights[attr] = {
            "w_agreement": round(float(w_agree), 3),
            "w_disagreement": round(float(w_disagree), 3)
        }
    return weights

def evaluate_probabilistic_linkage(
    pair_comparisons: list[dict[str, bool]],
    weights: dict[str, dict[str, float]],
    threshold_upper: float = 10.0,
    threshold_lower: float = 0.0
) -> list[dict]:
    results = []
    for idx, comp in enumerate(pair_comparisons):
        total_score = 0.0
        breakdown = {}
        for attr, agreed in comp.items():
            w_entry = weights[attr]
            delta_w = w_entry["w_agreement"] if agreed else w_entry["w_disagreement"]
            total_score += delta_w
            breakdown[attr] = round(delta_w, 3)

        if total_score >= threshold_upper:
            decision = "DEFINITE_MATCH"
        elif total_score <= threshold_lower:
            decision = "DEFINITE_NON_MATCH"
        else:
            decision = "POSSIBLE_MATCH_MANUAL_REVIEW"

        results.append({
            "pair_index": idx + 1,
            "total_fellegi_sunter_score": round(total_score, 3),
            "score_breakdown": breakdown,
            "linkage_decision": decision
        })
    return results

if __name__ == '__main__':
    attributes = {
        "ip_subnet": {"m_prob": 0.85, "u_prob": 0.05},
        "browser_os": {"m_prob": 0.92, "u_prob": 0.20},
        "geo_city": {"m_prob": 0.88, "u_prob": 0.08},
        "session_time_window": {"m_prob": 0.75, "u_prob": 0.15}
    }

    weights_table = calculate_fellegi_sunter_weights(attributes)
    print("=== FELLEGI-SUNTER ATTRIBUTE WEIGHTS TABLE ===")
    for attr, w in weights_table.items():
        print(f"  {attr:22} | Agreement: +{w['w_agreement']:>5.2f} bits | Disagreement: {w['w_disagreement']:>5.2f} bits")

    candidates = [
        {"ip_subnet": True, "browser_os": True, "geo_city": True, "session_time_window": True},
        {"ip_subnet": True, "browser_os": True, "geo_city": True, "session_time_window": False},
        {"ip_subnet": False, "browser_os": True, "geo_city": False, "session_time_window": False}
